function rg_seed_product($key,$name,$price,$cat,$image,$fields,$terms=[]){
    $found=get_posts(['post_type'=>'product','post_status'=>'any','meta_key'=>'_rg_seed_key','meta_value'=>$key,'numberposts'=>1,'fields'=>'ids']);
    if ($found) { return; }
    $p=new WC_Product_Simple();$p->set_name($name.' · Demo');$p->set_slug($key);$p->set_status('publish');$p->set_regular_price($price);$p->set_virtual(true);$p->set_image_id($image);$p->set_reviews_allowed(false);$p->set_description('Produto demonstrativo do portfólio fictício Raccolto Galvani. Nome, produtor e ficha são ilustrativos; fotografia de referência. Não disponível para compra real.');$p->set_short_description('Seleção demonstrativa — nenhuma compra real será realizada.');
    $term=get_term_by('slug',$cat,'product_cat');$p->set_category_ids([$term->term_id]);$p->update_meta_data('_rg_seed_key',$key);
    foreach ($fields as $k=>$v) {$p->update_meta_data('_rg_'.$k,$v);} $id=$p->save();
    foreach ($terms as $k=>$values) {wp_set_object_terms($id,$values,'rg_'.$k);}
}
